/* QUADFALL: an original falling-block puzzle with music and sound effects through the DAC.
 * Seven four-block pieces fall into a 10 x 20 well; fill rows to clear them. Speed grows every 10 rows.
 * Keys (5): << >> move (held: repeats), PLAY rotates, VOL soft drop (held: repeats; held 0.4 s: hard
 * drop), MENU pauses (resume / music track / effects on-off / quit). Best score in RAM (common/game.h).
 * Sound: modules/common/snd.c (non-blocking DAC sequencer, see there): one of three public-domain
 * tunes in our own arrangement (modules/quadfall/tunes.c, generated by tools/gen_quadfall_tunes.py)
 * that speeds up with the level, plus effects for move / rotate / lock / drop / 1-4 rows / level up /
 * game over. Every drawing helper calls snd_pump() between its small pieces (a cell = one LCD window
 * of 25 pixels), and the event loops poll instead of halting while sound is on.
 * Looks: 5 x 5 px "gem" cells (rounded corner, highlight, shade) on a dark well with a two-line frame;
 * the pieces' colours are our own palette. */
#include <stdint.h>
#include <string.h>
#include "../../hal/hal.h"
#include "../../core/event.h"
#include "../../core/module.h"
#include "../../core/config.h"
#include "../../apps/theme.h"
#include "../common/skin.h"
#include "../common/game.h"
#include "../common/snd.h"
#include "strings.h"
#include "tunes.h"

void beep(void) { snd_key(); }              /* game.c's gm_key: key blips through the sound engine */

#define CS 5                                /* cell size */
#define BW 10
#define BH 20
#define BX 6                                /* well: top left cell */
#define BY 18
#define PXL 64                              /* side panel */
#define C_WELL  RGB(14, 16, 34)
#define C_DOT   RGB(34, 38, 74)
#define C_FR1   RGB(150, 110, 255)
#define C_FR2   RGB(52, 36, 120)
#define C_LAB   RGB(130, 140, 190)
#define C_BAN   RGB(255, 205, 70)

enum { SP_EMPTY, SP_FLASH = 8, SP_GREY = 9, SP_TRAIL = 10, NSPR = 11 };
static uint8_t spr[NSPR][CS * CS * 2];      /* big-endian RGB565 cells (index 1..7 = piece + 1) */
static const uint8_t pcol[7][3] = {         /* I O T S Z J L */
    { 90, 235, 190 }, { 255, 205, 70 }, { 235, 95, 175 }, { 160, 225, 80 },
    { 240, 80, 70 }, { 110, 120, 255 }, { 255, 150, 60 } };
static const char gem[CS][CS + 1] = { ".ccc.", "cHccd", "ccccd", "cccdd", ".ddd." };

static const uint16_t shp[7][4] = {
    { 0x0F00, 0x2222, 0x00F0, 0x4444 }, { 0x6600, 0x6600, 0x6600, 0x6600 },
    { 0x4E00, 0x4640, 0x0E40, 0x4C40 }, { 0x6C00, 0x4620, 0x06C0, 0x8C40 },
    { 0xC600, 0x2640, 0x0C60, 0x4C80 }, { 0x8E00, 0x6440, 0x0E20, 0x44C0 },
    { 0x2E00, 0x4460, 0x0E80, 0xC440 } };
static uint8_t cofs[7][4][4];               /* the four cells of every piece / rotation: 4 * (y << 2 | x) - built by init_tables() */
static const uint8_t grav[15] = { 80, 70, 60, 52, 45, 38, 32, 26, 21, 17, 13, 10, 8, 6, 5 };   /* ticks per row */
static const uint16_t pts[5] = { 0, 100, 300, 500, 800 };
static const uint8_t *const fx_clr[4] = { fx_clear1, fx_clear2, fx_clear3, fx_clear4 };

/* ---- state ---------------------------------------------------------------------------------------------- */
static uint8_t bd[BH][BW];
static uint8_t pt, pr, nxt, bag[7], bag_i;
static int8_t  px, py;
static int8_t  ocx[4], ocy[4];              /* cells of the piece as drawn */
static uint8_t ocn;
static uint16_t score, lines, shown_score, shown_lines;
static uint8_t level, shown_level, start_lvl, trk, trk_run, fx_on, dirty;
static uint16_t fall_at, ban_until;
static uint8_t banner, dead;
static const uint8_t *pend_fx;
static int8_t  held;                        /* -1 / +1: << >> held */
static uint8_t vol_dn, hd_done;
static uint16_t rep_at, vol_t0, vol_rep;

#define D_SCORE 1
#define D_LEVEL 2
#define D_LINES 4
#define D_NEXT  8

/* ---- helpers -------------------------------------------------------------------------------------------- */
static void fx(const uint8_t *f, uint8_t prio) { if (fx_on) snd_sfx(f, prio); }

static void txt(uint8_t x, uint8_t y, const char *s, uint16_t fg, uint16_t bg)
{
    for (; *s; s++, x += FONT_W) { gfx_char(x, y, *s, 1, fg, bg); snd_pump(); }
}

/* gfx_fill in strips of at most ~200 pixels (~0.2 ms), the sound engine pumped after each */
static void fillp(uint8_t x, uint8_t y, uint8_t w, uint8_t h, uint16_t c)
{
    uint8_t n = 200 / w, k;
    if (!n) n = 1;
    while (h) {
        k = h < n ? h : n;
        gfx_fill(x, y, w, k, c);
        snd_pump();
        y += k; h -= k;
    }
}

static uint8_t qf_key(void)                 /* a key press, sound running meanwhile; GM_POWER on EV_POWER */
{
    event_t e;
    for (;;) {
        snd_pump();
        hal_watchdog();
        if (skin_get(&e)) {
            gm_seed(hal_ticks());
            if (e.type == EV_POWER) { MOD_POWER_REQ = 1; return GM_POWER; }
            if (e.type == EV_KEY_DOWN) { snd_key(); return e.code; }
        } else if (!snd_busy()) hal_idle();
    }
}

static uint16_t mix(uint8_t r, uint8_t g, uint8_t b, uint8_t k)   /* k/8 of the colour */
{
    return RGB((r * k) >> 3, (g * k) >> 3, (b * k) >> 3);
}

static void put(uint8_t i, uint8_t x, uint8_t y, uint16_t c)
{
    spr[i][(y * CS + x) * 2] = (uint8_t)(c >> 8);
    spr[i][(y * CS + x) * 2 + 1] = (uint8_t)c;
}

static void gem_sprite(uint8_t i, uint16_t c, uint16_t h, uint16_t d)
{
    uint8_t x, y;
    char ch;
    for (y = 0; y < CS; y++)
        for (x = 0; x < CS; x++) {
            ch = gem[y][x];
            put(i, x, y, ch == '.' ? C_WELL : ch == 'c' ? c : ch == 'H' ? h : d);
        }
}

static void build_sprites(void)
{
    uint8_t i, x, y, r, n;
    uint16_t m, bit;
    for (i = 0; i < 7; i++)                              /* cell offsets: no variable shifts at run time (SDCC loops them) */
        for (r = 0; r < 4; r++) {
            m = shp[i][r];
            bit = 0x8000;
            n = 0;
            for (x = 0; x < 16; x++, bit >>= 1)
                if (m & bit) cofs[i][r][n++] = x;
        }
    for (i = 0; i < 7; i++) {
        const uint8_t *c = pcol[i];
        uint8_t hi_r = c[0] > 165 ? 255 : c[0] + 90, hi_g = c[1] > 165 ? 255 : c[1] + 90, hi_b = c[2] > 165 ? 255 : c[2] + 90;
        gem_sprite(i + 1, RGB(c[0], c[1], c[2]), RGB(hi_r, hi_g, hi_b), mix(c[0], c[1], c[2], 5));
    }
    gem_sprite(SP_FLASH, RGB(235, 240, 255), RGB(255, 255, 255), RGB(170, 180, 215));
    gem_sprite(SP_GREY, RGB(96, 100, 128), RGB(150, 155, 185), RGB(56, 58, 80));
    for (y = 0; y < CS; y++)
        for (x = 0; x < CS; x++) {
            put(SP_EMPTY, x, y, x == 2 && y == 2 ? C_DOT : C_WELL);
            put(SP_TRAIL, x, y, x == 2 ? RGB(110, 100, 200) : C_WELL);
        }
}

static void cell(uint8_t c, uint8_t r, uint8_t s)
{
    hal_lcd_window(BX + c * CS, BY + r * CS, CS, CS);
    hal_lcd_blit(spr[s], CS * CS);
    snd_pump();
}

static void rows_draw(uint8_t r0, uint8_t r1)           /* rows r0..r1 of the well from the board */
{
    uint8_t r, c;
    for (r = r0; r <= r1; r++)
        for (c = 0; c < BW; c++) cell(c, r, bd[r][c]);
}

static void frame(void)
{
    fillp(BX - 2, BY - 2, BW * CS + 4, BH * CS + 4, C_FR1);
    fillp(BX - 1, BY - 1, BW * CS + 2, BH * CS + 2, C_FR2);
}

/* ---- side panel ------------------------------------------------------------------------------------------ */
static void value(uint8_t y, uint16_t v)                /* right-padded to 6 columns */
{
    char b[8];
    uint8_t n;
    strcpy(b, gm_num(v));
    n = (uint8_t)strlen(b);
    while (n < 6) b[n++] = ' ';
    b[n] = 0;
    txt(PXL + 2, y, b, sk.fg, sk.bg);
}

static void next_draw(void)
{
    uint8_t i, c, r, v, minc = 4, maxc = 0, minr = 4, maxr = 0, x0, y0;
    for (i = 0; i < 4; i++) {
        v = cofs[nxt][0][i];
        c = v & 3; r = v >> 2;
        if (c < minc) minc = c;
        if (c > maxc) maxc = c;
        if (r < minr) minr = r;
        if (r > maxr) maxr = r;
    }
    fillp(PXL, 28, 26, 16, C_FR2);
    fillp(PXL + 1, 29, 24, 14, C_WELL);
    x0 = PXL + 2 + (20 - (maxc - minc + 1) * CS) / 2 - minc * CS;
    y0 = 30 + (10 - (maxr - minr + 1) * CS) / 2 - minr * CS;
    for (i = 0; i < 4; i++) {
        v = cofs[nxt][0][i];
        hal_lcd_window(x0 + (v & 3) * CS, y0 + (v >> 2) * CS, CS, CS);
        hal_lcd_blit(spr[nxt + 1], CS * CS);
        snd_pump();
    }
}

static void panel_labels(void)
{
    txt(PXL + 2, 18, T(S_NEXT), C_LAB, sk.bg);
    txt(PXL + 2, 50, T(S_SCORE), C_LAB, sk.bg);
    txt(PXL + 2, 74, T(S_LEVEL), C_LAB, sk.bg);
    txt(PXL + 2, 98, T(S_LINES), C_LAB, sk.bg);
}

static void panel(void)                                  /* what changed */
{
    if (dirty & D_SCORE) value(59, score);
    if (dirty & D_LEVEL) value(83, level);
    if (dirty & D_LINES) value(107, lines);
    if (dirty & D_NEXT) next_draw();
    dirty = 0;
}

/* ---- pieces ----------------------------------------------------------------------------------------------- */
static void cells(uint8_t t, uint8_t r, int8_t x, int8_t y, int8_t *cx, int8_t *cy)
{
    const uint8_t *o = cofs[t][r];
    uint8_t i;
    for (i = 0; i < 4; i++) { cx[i] = x + (o[i] & 3); cy[i] = y + (o[i] >> 2); }
}

static uint8_t collide(uint8_t t, uint8_t r, int8_t x, int8_t y)
{
    int8_t cx[4], cy[4];
    uint8_t i;
    cells(t, r, x, y, cx, cy);
    for (i = 0; i < 4; i++) {
        if (cx[i] < 0 || cx[i] >= BW || cy[i] >= BH) return 1;
        if (cy[i] >= 0 && bd[cy[i]][cx[i]]) return 1;
    }
    return 0;
}

static uint8_t in_set(const int8_t *cx, const int8_t *cy, int8_t x, int8_t y)
{
    uint8_t i;
    for (i = 0; i < 4; i++) if (cx[i] == x && cy[i] == y) return 1;
    return 0;
}

static void show_piece(void)                             /* draw the piece, only the cells that changed */
{
    int8_t cx[4], cy[4];
    uint8_t i;
    snd_pump();
    cells(pt, pr, px, py, cx, cy);
    if (ocn)
        for (i = 0; i < 4; i++)
            if (ocy[i] >= 0 && !in_set(cx, cy, ocx[i], ocy[i])) cell(ocx[i], ocy[i], SP_EMPTY);
    snd_pump();
    for (i = 0; i < 4; i++)
        if (cy[i] >= 0 && !(ocn && in_set(ocx, ocy, cx[i], cy[i]))) cell(cx[i], cy[i], pt + 1);
    for (i = 0; i < 4; i++) { ocx[i] = cx[i]; ocy[i] = cy[i]; }
    ocn = 1;
}

static void hide_piece(void)
{
    uint8_t i;
    if (ocn) for (i = 0; i < 4; i++) if (ocy[i] >= 0) cell(ocx[i], ocy[i], SP_EMPTY);
    ocn = 0;
}

static uint8_t next_piece(void)
{
    uint8_t i, j, t;
    if (bag_i >= 7) {                                    /* a shuffled bag of the seven */
        for (i = 0; i < 7; i++) bag[i] = i;
        for (i = 6; i; i--) { j = gm_randn(i + 1); t = bag[i]; bag[i] = bag[j]; bag[j] = t; }
        bag_i = 0;
    }
    return bag[bag_i++];
}

static void grav_reset(void) { fall_at = hal_ticks() + grav[level > 14 ? 14 : level]; }

static uint8_t spawn(void)                               /* 0 = no room: game over */
{
    pt = nxt; nxt = next_piece();
    pr = 0; px = 3; py = 0; ocn = 0;
    dirty |= D_NEXT;
    grav_reset();
    if (collide(pt, pr, px, py)) return 0;
    show_piece();
    return 1;
}

static uint8_t try_move(int8_t dx, int8_t dy)
{
    if (collide(pt, pr, px + dx, py + dy)) return 0;
    px += dx; py += dy;
    show_piece();
    return 1;
}

static void rotate(void)
{
    static const int8_t kick[5] = { 0, -1, 1, -2, 2 };
    uint8_t r = (pr + 1) & 3, i;
    for (i = 0; i < (pt == 1 ? 1 : pt == 0 ? 5 : 3); i++) {  /* O: no kick; I: wide kicks */
        snd_pump();
        if (!collide(pt, r, px + kick[i], py)) {
            px += kick[i]; pr = r;
            show_piece();
            fx(fx_rot, 1);
            return;
        }
    }
}

static void add_score(uint16_t v)
{
    score = score > 65535 - v ? 65535 : score + v;
    dirty |= D_SCORE;
}

/* ---- locking, rows ----------------------------------------------------------------------------------------- */
static void banner_show(void)
{
    uint8_t y = BY + 8 * CS + 2;
    fillp(BX, y, BW * CS, 14, C_BAN);
    fillp(BX + 1, y + 1, BW * CS - 2, 12, C_FR2);
    txt(BX + (BW * CS - 8 * FONT_W) / 2, y + 3, T(S_LVLUP), C_BAN, C_FR2);
    banner = 1;
    ban_until = hal_ticks() + 150;
}

static void banner_end(void)
{
    banner = 0;
    rows_draw(8, 10);
    if (ocn) { ocn = 0; show_piece(); }
}

static void clear_rows(int8_t r0)                        /* r0: first row the locked piece touched (it spans 4) */
{
    uint8_t full[BH], nf = 0, r, c, top, dst, k, maxr = 0, r1;
    memset(full, 0, sizeof full);
    if (r0 < 0) r0 = 0;
    r1 = r0 + 3 < BH ? r0 + 3 : BH - 1;
    for (r = r0; r <= r1; r++) {                         /* only those rows can have become full */
        full[r] = 1;
        for (c = 0; c < BW; c++) if (!bd[r][c]) { full[r] = 0; break; }
        if (full[r]) { nf++; maxr = r; }
    }
    snd_pump();
    if (!nf) return;
    fx(fx_clr[nf - 1], 2);
    for (k = 0; k < 6; k++) {                            /* flash the rows */
        for (r = 0; r < BH; r++)
            if (full[r]) for (c = 0; c < BW; c++) cell(c, r, k & 1 ? bd[r][c] : SP_FLASH);
        snd_wait(5);
    }
    for (top = 0; top < BH; top++) { snd_pump(); for (c = 0; c < BW && !bd[top][c]; c++) ; if (c < BW) break; }
    dst = BH - 1;
    for (r = BH; r--; )
        if (!full[r]) { if (dst != r) memcpy(bd[dst], bd[r], BW); dst--; }
    for (r = 0; r <= dst; r++) memset(bd[r], 0, BW);
    rows_draw(top, maxr);
    add_score(pts[nf] * (level + 1));
    lines += nf;
    dirty |= D_LINES;
    k = lines / 10;
    if (k < start_lvl) k = start_lvl;
    if (k > level) {
        level = k;
        dirty |= D_LEVEL;
        snd_tempo(level);
        pend_fx = fx_level;                              /* after the row effect has played */
        banner_show();
    }
}

static void lock_piece(uint8_t flash)
{
    int8_t cx[4], cy[4];
    uint8_t i;
    snd_pump();
    cells(pt, pr, px, py, cx, cy);
    for (i = 0; i < 4; i++) if (cy[i] >= 0) bd[cy[i]][cx[i]] = pt + 1;
    fx(fx_lock, 1);
    if (flash) {
        for (i = 0; i < 4; i++) if (cy[i] >= 0) cell(cx[i], cy[i], SP_FLASH);
        snd_wait(3);
        for (i = 0; i < 4; i++) if (cy[i] >= 0) cell(cx[i], cy[i], pt + 1);
    }
    ocn = 0;
    clear_rows(py);
}

static void hard_drop(void)
{
    int8_t cx[4], cy[4], top0[BW];
    uint8_t i, c, n = 0, r;
    cells(pt, pr, px, py, cx, cy);
    for (c = 0; c < BW; c++) top0[c] = 127;
    for (i = 0; i < 4; i++) if (cx[i] >= 0 && cy[i] < top0[cx[i]]) top0[cx[i]] = cy[i];
    while (!collide(pt, pr, px, py + 1)) { py++; n++; }
    if (n) {
        hide_piece();
        show_piece();
        cells(pt, pr, px, py, cx, cy);                   /* the trail: one thin line per column above the piece */
        for (c = 0; c < BW; c++) {
            int8_t yb = 127;
            if (top0[c] == 127) continue;
            for (i = 0; i < 4; i++) if (cx[i] == c && cy[i] < yb) yb = cy[i];
            for (r = top0[c]; r < yb; r++) cell(c, r, SP_TRAIL);
        }
        fx(fx_drop, 1);
        add_score(2 * n);
        snd_wait(3);
        for (c = 0; c < BW; c++) {
            int8_t yb = 127;
            if (top0[c] == 127) continue;
            for (i = 0; i < 4; i++) if (cx[i] == c && cy[i] < yb) yb = cy[i];
            for (r = top0[c]; r < yb; r++) cell(c, r, SP_EMPTY);
        }
    }
    lock_piece(1);
}

/* ---- screens ------------------------------------------------------------------------------------------------ */
static void play_area_clear(void)
{
    gfx_fill(0, SKIN_TITLE_H, LCD_W, LCD_H - SKIN_TITLE_H, sk.bg);
}

static void well_all(void)
{
    frame();
    rows_draw(0, BH - 1);
    if (ocn) { ocn = 0; show_piece(); }
    panel_labels();
    dirty = D_SCORE | D_LEVEL | D_LINES | D_NEXT;
    panel();
}

/* pause menu: 0 resume, 1 quit, 2 power */
static const uint8_t trk_str[4] = { S_TRK_A, S_TRK_B, S_TRK_C, S_OFF };
static void menu_line(uint8_t i, uint8_t sel)
{
    uint8_t y = 51 + i * 11;
    const char *l, *v = 0;
    uint16_t fg = sel ? C_SEL : sk.fg;
    switch (i) {
    case 0: l = T(S_RESUME); break;
    case 1: l = T(S_MUSIC); v = T(trk_str[trk]); break;
    case 2: l = T(S_FX); v = T(fx_on ? S_ON : S_OFF); break;
    default: l = T(S_QUIT); break;
    }
    fillp(5, y - 1, 118, 10, sk.bg);
    if (sel) gfx_char(6, y, '>', 1, C_SEL, sk.bg);
    txt(12, y, l, fg, sk.bg);
    if (v) txt(LCD_W - 4 - (uint8_t)strlen(v) * FONT_W, y, v, fg, sk.bg);
}

static uint8_t pause_menu(void)
{
    uint8_t sel = 0, i, k, old = trk;
    snd_music_pause(1);
    snd_wait(3);                                         /* the fade-out (16 ms) before the long fills: no held sample */
    fillp(2, 35, 124, 76, sk.sel_bot);
    fillp(3, 36, 122, 74, sk.bg);
    gm_text_c(39, T(S_PAUSE), C_SEL, sk.bg);
    gm_text_c(98, T(S_HINT), sk.dim, sk.bg);
    for (i = 0; i < 4; i++) menu_line(i, i == sel);
    for (;;) {
        k = qf_key();
        if (k == GM_POWER) return 2;
        if (k == KEY_MENU) break;
        if (k == KEY_LEFT || k == KEY_RIGHT || k == KEY_VOL) {
            i = sel;
            sel = k == KEY_LEFT ? (sel ? sel - 1 : 3) : (sel == 3 ? 0 : sel + 1);
            menu_line(i, 0);
            menu_line(sel, 1);
        } else if (k == KEY_PLAY) {
            if (sel == 0) break;
            if (sel == 3) return 1;
            if (sel == 1) trk = trk == 3 ? 0 : trk + 1;
            else fx_on = !fx_on;
            menu_line(sel, 1);
        }
    }
    {
        gscore_t *g = gm_scores();
        g->quad_trk = trk; g->quad_nofx = !fx_on;
        gm_scores_save();
    }
    play_area_clear();
    well_all();
    if (banner) banner_show();
    if (trk != old || trk_run != trk) {
        trk_run = trk;
        snd_music(trk < 3 ? &tunes[trk] : 0, level);
    } else if (trk < 3) snd_music_pause(0);
    return 0;
}

static void game_over_fx(void)
{
    uint8_t r, c;
    snd_music(0, 0);
    hide_piece();
    for (r = BH; r--; ) {
        for (c = 0; c < BW; c++) cell(c, r, SP_GREY);
        snd_wait(2);
    }
}

/* one game: 0 = title, 1 = again, 2 = power */
static uint8_t game(void)
{
    event_t e;
    uint8_t k, r;
    uint16_t now;
    gscore_t *g;
    memset(bd, 0, sizeof bd);
    score = lines = 0; level = start_lvl; held = 0; vol_dn = 0; banner = 0; pend_fx = 0; bag_i = 7;
    ocn = 0; hd_done = 0;
    gm_seed(hal_ticks());
    nxt = next_piece();
    play_area_clear();
    spawn();
    well_all();
    snd_tempo(level);
    trk_run = trk;
    if (trk < 3) snd_music(&tunes[trk], level);
    grav_reset();
    for (;;) {
        snd_pump();
        hal_watchdog();
        while (skin_get(&e)) {
            if (e.type == EV_POWER) { MOD_POWER_REQ = 1; return 2; }
            snd_pump();
            k = e.code;
            if (e.type == EV_KEY_DOWN) {
                now = hal_ticks();
                if (k == KEY_LEFT || k == KEY_RIGHT) {
                    held = k == KEY_LEFT ? -1 : 1;
                    vol_dn = 0;
                    if (try_move(held, 0)) fx(fx_move, 0);
                    rep_at = now + 16;
                } else if (k == KEY_PLAY) {
                    rotate();
                } else if (k == KEY_VOL) {
                    held = 0;
                    vol_dn = 1; hd_done = 0; vol_t0 = now; vol_rep = now + 5;
                    if (try_move(0, 1)) { add_score(1); grav_reset(); }
                    else lock_piece(1), dead = !spawn();
                } else if (k == KEY_MENU) {
                    held = 0; vol_dn = 0;
                    r = pause_menu();
                    if (r) { g = gm_scores(); (void)g; snd_music(0, 0); return r == 2 ? 2 : 0; }
                    grav_reset();
                }
            } else if (e.type == EV_KEY_UP) {
                if ((k == KEY_LEFT && held < 0) || (k == KEY_RIGHT && held > 0)) held = 0;
                else if (k == KEY_VOL) vol_dn = 0;
            }
            if (dead) break;
        }
        if (!dead) {
            now = hal_ticks();
            if (held && (int16_t)(now - rep_at) >= 0) {
                if (try_move(held, 0)) fx(fx_move, 0);
                rep_at += 5;
            }
            if (vol_dn && !hd_done) {
                if ((int16_t)(now - vol_t0) >= 40) { hd_done = 1; hard_drop(); dead = !spawn(); }
                else if ((int16_t)(now - vol_rep) >= 0) {
                    vol_rep += 5;
                    if (try_move(0, 1)) { add_score(1); grav_reset(); }
                    else { hd_done = 1; lock_piece(1); dead = !spawn(); }
                }
            }
            if ((int16_t)(now - fall_at) >= 0) {
                if (try_move(0, 1)) grav_reset();
                else { lock_piece(1); dead = !spawn(); }
            }
            if (banner && (int16_t)(now - ban_until) >= 0) banner_end();
            if (pend_fx && !snd_sfx_busy()) { fx(pend_fx, 3); pend_fx = 0; }
            if (dirty) panel();
        }
        if (dead) break;
        if (!snd_busy()) hal_idle();
    }
    dead = 0;
    game_over_fx();
    g = gm_scores();
    r = score > g->quad_best;
    if (r) { g->quad_best = score; gm_scores_save(); }
    panel();
    {
        char b[20];
        strcpy(b, T(S_SCORE)); strcat(b, " "); strcat(b, gm_num(score));
        gm_box(4, T(S_OVER), b, r ? T(S_NEWBEST) : 0, T(S_AGAIN), RGB(255, 90, 80));
    }
    fx(fx_over, 3);
    snd_wait(50);                                        /* half a second to let go of the keys */
    k = qf_key();
    while (snd_sfx_busy()) { snd_pump(); hal_watchdog(); }
    if (k == GM_POWER) return 2;
    return k == KEY_MENU ? 0 : 1;
}

static void mini(uint8_t t, uint8_t r, uint8_t x, uint8_t y)    /* a piece at pixel x, y */
{
    uint8_t i, v;
    for (i = 0; i < 4; i++) {
        v = cofs[t][r][i];
        hal_lcd_window(x + (v & 3) * CS, y + (v >> 2) * CS, CS, CS);
        hal_lcd_blit(spr[t + 1], CS * CS);
    }
}

/* title screen: 1 = play, 0 = leave */
static uint8_t title(void)
{
    uint8_t k, i;
    gscore_t *g = gm_scores();
    char b[22];
    play_area_clear();
    gfx_text(8, 20, "QUAD", 3, C_FR1, sk.bg);
    gfx_text(8, 46, "FALL", 3, C_BAN, sk.bg);
    mini(5, 0, 86, 18);                                  /* a few pieces stacking up beside the logo */
    mini(3, 0, 100, 28);
    mini(1, 0, 78, 34);
    mini(0, 1, 102, 40);
    mini(6, 2, 84, 50);
    for (i = 0; i < 4; i++) gfx_text(8, 70 + i * 9, T(S_H_MOVE + i), 1, sk.fg, sk.bg);
    for (;;) {
        strcpy(b, "< "); strcat(b, T(S_LEVEL)); strcat(b, " "); strcat(b, gm_num(start_lvl));
        strcat(b, " >  "); strcat(b, T(S_BEST)); strcat(b, " "); strcat(b, gm_num(g->quad_best));
        gfx_fill(0, 106, LCD_W, 10, sk.bg);
        gm_text_c(107, b, C_BAN, sk.bg);
        skin_footer(T(S_START));
        k = qf_key();
        if (k == KEY_PLAY) return 1;
        if (k == KEY_MENU || k == GM_POWER) return 0;
        if (k == KEY_LEFT && start_lvl) start_lvl--;
        if (k == KEY_RIGHT && start_lvl < 9) start_lvl++;
    }
}

uint16_t mod_main(void)
{
    uint8_t r;
    gscore_t *g;
    skin_load();
    gm_seed(hal_ticks());
    g = gm_scores();
    trk = g->quad_trk > 3 ? 0 : g->quad_trk;
    fx_on = !g->quad_nofx;
    build_sprites();
    snd_init();
    skin_title(T(S_TITLE));
    while (title()) {
        do r = game(); while (r == 1);
        if (r == 2) break;
    }
    snd_exit();
    return 0;
}
